const norm = (f) => readFileSync(f, "utf-8").replace(/\r\n/g, "\n");
if (installed) {
  for (const f of UPGRADE) { if (!existsSync(f)) fail(f + " is missing"); if (norm(f) !== BASE[f]) fail(f + " was changed after the first Quality Technician update, so it cannot be replaced safely. Send me this message."); }
  for (const f of NEWEQ) if (existsSync(f)) fail(f + " already exists");
} else {
  if (!existsSync("client/src/data/courses/meal.ts")) fail("run update-meal-course.mjs first (this update builds on it)");
  for (const f of Object.keys(TEXT)) if (existsSync(f)) fail("unexpected file " + f + " — the course seems partly installed. Send me this message.");
}
